CREATE TRIGGER `documents_note_parent_required_insert` BEFORE INSERT ON `documents` WHEN NEW.type IN ('credit_note', 'debit_note') AND NEW.parent_id IS NULL BEGIN SELECT RAISE(ABORT, 'documents_note_parent_required_insert: a credit or debit note names its invoice'); END;
