CREATE TRIGGER `documents_note_parent_required_update` BEFORE UPDATE OF parent_id, type ON `documents` WHEN NEW.type IN ('credit_note', 'debit_note') AND NEW.parent_id IS NULL BEGIN SELECT RAISE(ABORT, 'documents_note_parent_required_update: a credit or debit note names its invoice'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_note_issue_check` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND NEW.type IN ('credit_note', 'debit_note') AND NOT EXISTS (SELECT 1 FROM documents p WHERE p.id = NEW.parent_id AND p.type IN ('tax_invoice', 'export_invoice') AND p.frozen_at IS NOT NULL AND p.status IN ('issued', 'partially_paid', 'paid', 'partially_credited') AND p.client_id = NEW.client_id AND p.currency = NEW.currency AND p.supply_type IS NEW.supply_type AND p.place_of_supply_code IS NEW.place_of_supply_code AND p.fx_rate_micros IS NEW.fx_rate_micros AND p.export_mode IS NEW.export_mode) BEGIN SELECT RAISE(ABORT, 'documents_note_issue_check: the invoice of a note must be an issued, live invoice of the same client and currency, with the same supply, rate and route'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_credit_note_cap` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND NEW.type IN ('credit_note', 'debit_note') AND NEW.type = 'credit_note' AND EXISTS (SELECT 1 FROM documents p, (SELECT coalesce(sum(c.total_minor), 0) AS total_minor, coalesce(sum(c.taxable_minor), 0) AS taxable_minor, coalesce(sum(c.cgst_minor), 0) AS cgst_minor, coalesce(sum(c.sgst_minor), 0) AS sgst_minor, coalesce(sum(c.igst_minor), 0) AS igst_minor, coalesce(sum(c.total_inr_minor), 0) AS total_inr_minor FROM documents c WHERE c.parent_id = NEW.parent_id AND c.type = 'credit_note' AND c.frozen_at IS NOT NULL AND c.status <> 'void' AND c.id <> NEW.id) s WHERE p.id = NEW.parent_id AND (NEW.total_minor > p.total_minor - s.total_minor OR NEW.taxable_minor > p.taxable_minor - s.taxable_minor OR NEW.cgst_minor > p.cgst_minor - s.cgst_minor OR NEW.sgst_minor > p.sgst_minor - s.sgst_minor OR NEW.igst_minor > p.igst_minor - s.igst_minor OR NEW.total_inr_minor > p.total_inr_minor - s.total_inr_minor)) BEGIN SELECT RAISE(ABORT, 'documents_credit_note_cap: the credit notes of an invoice cannot add up to more than the invoice, in total or in any tax head'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_ledger_bounds` BEFORE UPDATE OF credited_minor, balance_minor ON `documents` WHEN NEW.credited_minor < 0 OR NEW.credited_minor > NEW.total_minor OR NEW.balance_minor < 0 BEGIN SELECT RAISE(ABORT, 'documents_ledger_bounds: credited is between zero and the total, and the balance is never negative'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_note_no_void` BEFORE UPDATE OF status ON `documents` WHEN NEW.status = 'void' AND OLD.type IN ('credit_note', 'debit_note') BEGIN SELECT RAISE(ABORT, 'documents_note_no_void: a credit or debit note is never voided'); END;
