CREATE TRIGGER `documents_ims_status_insert` BEFORE INSERT ON `documents` WHEN NEW.ims_status IS NOT NULL BEGIN SELECT RAISE(ABORT, 'documents_ims_status_insert: the IMS status is set once at the issue of a credit note, and a pending one is answered once'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_ims_status_update` BEFORE UPDATE OF ims_status ON `documents` WHEN NEW.ims_status IS NOT OLD.ims_status AND NOT coalesce((OLD.ims_status IS NULL AND NEW.ims_status IN ('pending', 'not_applicable') AND OLD.type = 'credit_note' AND OLD.frozen_at IS NULL AND NEW.frozen_at IS NOT NULL) OR (OLD.ims_status IS 'pending' AND NEW.ims_status IN ('accepted', 'rejected') AND OLD.type = 'credit_note' AND OLD.frozen_at IS NOT NULL), 0) BEGIN SELECT RAISE(ABORT, 'documents_ims_status_update: the IMS status is set once at the issue of a credit note, and a pending one is answered once'); END;
