CREATE TRIGGER `documents_credit_note_ims_required` BEFORE UPDATE OF status ON `documents` WHEN OLD.status = 'draft' AND NEW.status = 'issued' AND NEW.type IN ('credit_note', 'debit_note') AND NEW.type = 'credit_note' AND NEW.ims_status IS NULL BEGIN SELECT RAISE(ABORT, 'documents_credit_note_ims_required: a credit note is issued with its IMS status set (pending or not applicable)'); END;
